const incoming = $input.first().json;
const event = incoming.body ?? incoming;
const allowedTypes = new Set(['integration.test', 'lead.created', 'lead.updated']);

if (event.version !== '1') {
  throw new Error('Unsupported Revora event version');
}
if (typeof event.id !== 'string' || event.id.length < 16) {
  throw new Error('Invalid Revora event id');
}
if (!allowedTypes.has(event.type)) {
  throw new Error('Unsupported Revora event type');
}
if (typeof event.organization_id !== 'string' || !event.organization_id) {
  throw new Error('Invalid Revora organization');
}
if (!event.data || typeof event.data !== 'object') {
  throw new Error('Invalid Revora event data');
}

return [{ json: { accepted: true, event_id: event.id, event_type: event.type, organization_id: event.organization_id } }];
